insert into cisco.cisco_decks (id, slug, title, sermon_id, metadata)
insert into cisco.cisco_slides (deck_id, position, html, outline_html, bg, notes)
values
  ('c1000000-0000-4000-8000-000000000011', 1, '<img class="slide-image" src="/sermons/the-father-who-never-gave-up/slides/01.jpg" alt="The Family of God: The Father Who Never Gave Up. His love never stopped reaching. Romans 8:15, November 1, 2026.">', '<p><strong>Opening &mdash; The Son of Thy love</strong></p><p><strong>[Video: We Praise Thee, O God]</strong></p><p>&bull; Did you hear the opening line? The reason we praise God&hellip; <strong>&ldquo;for the Son of Thy love.&rdquo;</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 2, '<img class="slide-image" src="/sermons/the-father-who-never-gave-up/slides/02.jpg" alt="The Family of God, a five-part series: The Father Who Never Gave Up; A Place to Belong; Learning to Love Like Family; Thankful to Be His; The Family Business.">', '<p><strong>The new series</strong></p><p>Over the next five Sundays, we&rsquo;re going to look at something that runs throughout the entire Bible:</p><p><strong>God&rsquo;s desire to have a relationship with us. Not simply as our Creator, but as our Father.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 3, '<img class="slide-image" src="/sermons/the-father-who-never-gave-up/slides/03.jpg" alt="The Old Testament is a story of the distance God went to in order to show us how much He loves us.">', '<p><strong>God reaches out to us in the OT&hellip;</strong></p><p>How far would you go to show your love to someone, to convince someone that you love them?</p><p>&bull; <strong>The Old Testament reveals how far God was willing to go.</strong></p><p>&bull; What God was teaching: how much He loves His people, and how much they need their Creator.</p><p>&bull; Throughout the OT God was patient, merciful, gracious while He worked His plan.</p><p>&bull; The lessons are timeless &mdash; not just for the house of Israel, but for humanity.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 4, '<img class="slide-image" src="/sermons/the-father-who-never-gave-up/slides/04.jpg" alt="God doesn’t simply want to rescue us. He wants us home.">', '<p><strong>The first responder</strong></p><p>&bull; A firefighter saves a child in a burning home.</p><p>&bull; But what if the child inside that burning house were his own son or daughter?</p><p>&bull; <strong>God doesn&rsquo;t simply want to rescue us. He wants us home.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 5, '<img class="slide-image" src="/sermons/the-father-who-never-gave-up/slides/05.jpg" alt="Meet Jefferson Fisher: trial attorney from Texas, helps people have better, more thoughtful conversations, author of The Next Conversation.">', '<p><strong>Are we hearing God?</strong></p><p>&bull; Introduce Jefferson. His book, <em>The Next Conversation</em>.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 6, '<video class="slide-video" src="https://media.fivesixteen.church/videos/cisco/ag8wccpm/mvz8zspa.mp4" poster="https://media.fivesixteen.church/videos/cisco/ag8wccpm/mvz8zspa-poster.jpg" title="Jefferson Fisher: Is what I say what people hear?" controls playsinline preload="none"></video>', '<p><strong>[Video: Jefferson Fisher 001 &mdash; &ldquo;Is what I say what people hear?&rdquo;]</strong></p><p>Questions following the videoclip:</p><p>&bull; What is God trying to communicate to us?</p><p>&bull; What are you hearing?</p><p>&bull; How do you hear God?</p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 7, '<img class="slide-image" src="/sermons/the-father-who-never-gave-up/slides/06.jpg" alt="What do you see when you see God creating man?">', '<p>Do we finally get what God has been trying to communicate to us (since Adam and Eve)?</p><p>&bull; What do you see when you see God creating man?</p><p>&bull; When He walks in the garden?</p><p>&bull; God&rsquo;s desire was not merely to have people worship Him <strong>(it&rsquo;s about family).</strong></p><p><strong>Many understandings of God</strong></p><p>&bull; <strong>Judaism</strong> recognizes God as Father but does not accept Jesus as His divine Son.</p><p>&bull; <strong>Islam</strong> emphasizes submission to one God but rejects the idea that God has a Son.</p><p>&bull; <strong>Hinduism and Buddhism</strong> have very different understandings of ultimate reality and spiritual liberation.</p><p><strong>At the heart of Christianity: God loves us so deeply that He gave His Son &mdash; not simply to save us, but to bring us into His family.</strong></p><p>&bull; The temple and the Ark were not God&rsquo;s ultimate vision of His presence.</p><p>&bull; Paul: the new covenant is God living in us. The distance barrier has been removed.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 8, '<img class="slide-image" src="/sermons/the-father-who-never-gave-up/slides/07.jpg" alt="The Power of the Christian Story: God’s Motivation, John 3:16; God’s Demonstration, Romans 5:8; God’s Invitation, Romans 8:15.">', '<p><strong>The New Testament&rsquo;s Father&ndash;Child Story</strong></p><p>God wasn&rsquo;t simply trying to change Israel&rsquo;s behavior. He was working toward a relationship fulfilled through Jesus Christ.</p><p>&bull; John 3:16 &mdash; God&rsquo;s <strong>motivation</strong></p><p>&bull; Romans 5:8 &mdash; God&rsquo;s <strong>demonstration</strong></p><p>&bull; Romans 8:15 &mdash; God&rsquo;s <strong>invitation</strong></p><p><strong>&ldquo;God didn&rsquo;t simply create a world He could rule. He created people He could love.&rdquo;</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 9, '<img class="slide-image" src="/sermons/the-father-who-never-gave-up/slides/08.jpg" alt="The greatest gift God offers us isn’t simply a place in heaven. It’s a place in His family.">', '<p><strong>&ldquo;The greatest gift God offers us isn&rsquo;t simply a place in heaven. It&rsquo;s a place in His family.&rdquo;</strong></p><p><strong>Keeping the door open (God&rsquo;s persistence)</strong></p><p>What would it take for us to truly believe that a relationship with God as His son/daughter is better than anything out there?</p><p>&bull; Can we be convinced?</p><p>&bull; Why is this so hard to believe and fully understand?</p><p><strong>Reality check:</strong> Many of our deeply held beliefs are rooted in our core.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 10, '<video class="slide-video" src="https://media.fivesixteen.church/videos/cisco/qn569q9c/mvzaqpc3.mp4" poster="https://media.fivesixteen.church/videos/cisco/qn569q9c/mvzaqpc3-poster.jpg" title="Jefferson Fisher: If you can’t be a bridge, be a lighthouse" controls playsinline preload="none"></video>', '<p><strong>[Video: Jefferson Fisher 002]</strong></p><p>&bull; Our beliefs have deep roots &mdash; turning someone around can take a long time.</p><p>&bull; When you <strong>can&rsquo;t be a bridge, be a lighthouse.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 11, '<img class="slide-image" src="/sermons/the-father-who-never-gave-up/slides/09.jpg" alt="The lighthouse helps us find our way, but the bridge allows us to come home.">', '<p>&bull; God wants us to cross the bridge, move closer to Him. God wants to close the gap between us and Him.</p><p>&bull; A lighthouse doesn&rsquo;t force anyone to come home. It simply keeps shining so they can find their way back.</p><p>&bull; <strong>The lighthouse helps us find our way, but the bridge allows us to come home.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 12, '<img class="slide-image" src="/sermons/the-father-who-never-gave-up/slides/10.jpg" alt="Luke 15, The Prodigal Son: Love doesn’t always prevent someone from walking away. Sometimes we have to remember the goodness of the Father before we’re willing to return to Him. The father didn’t make the inheritance the issue; the relationship mattered more.">', '<p><strong>The father never gave up &mdash; Luke 15</strong></p><p>&bull; The son took his inheritance &mdash; the father gave him space.</p><p>&bull; Love doesn&rsquo;t always prevent someone from walking away.</p><p>&bull; The son realized what he had done &mdash; and decided to go home.</p><p>&bull; Sometimes we have to remember the goodness of the Father before we&rsquo;re willing to return to Him.</p><p>&bull; The father didn&rsquo;t make the inheritance the issue &mdash; the relationship mattered more.</p><p><strong>The son came home looking for a place to work. The father welcomed him back as a son.</strong></p><p><strong>The God who spent generations preparing the way for His Son is the same God who invites us to become His sons and daughters.</strong> Romans 8:15</p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 13, '<img class="slide-image" src="/sermons/the-father-who-never-gave-up/slides/11.jpg" alt="The Bible is the story of a Father restoring His family: Genesis 1–2, God creates humanity for fellowship with Him; Genesis 3, sin breaks that fellowship; the Old Testament, God prepares the way for restoration; the New Testament, through Jesus, God welcomes us into His family.">', '<p><strong>Closing &mdash; the Bible&rsquo;s larger story</strong></p><p>&bull; Genesis 1&ndash;2: God creates humanity for fellowship with Him.</p><p>&bull; Genesis 3: Sin breaks that fellowship.</p><p>&bull; The Old Testament: God prepares the way for restoration.</p><p>&bull; The New Testament: Through Jesus, God welcomes us into His family.</p><p>The New Testament brings something into much sharper focus: our adoption as God&rsquo;s children.</p><p>&bull; Romans 8:15&ndash;16 &mdash; We can <strong>CRY</strong> out, &ldquo;Abba, Father.&rdquo;</p><p>&bull; That&rsquo;s a relationship characterized by love, belonging, and intimacy rather than fear.</p><p>&bull; We don&rsquo;t simply recognize God as our Creator. We come to know Him as our Father.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000011', 14, '<img class="slide-image" src="/sermons/the-father-who-never-gave-up/slides/12.jpg" alt="God didn’t send Jesus simply to save us from something. He sent Jesus to bring us back to Someone.">', '<p><strong>God doesn&rsquo;t simply want our obedience. He wants our hearts.</strong></p><p><strong>God didn&rsquo;t send Jesus simply to save us from something. He sent Jesus to bring us back to Someone.</strong></p>', null, null)
insert into cisco.cisco_deck_state (deck_id, current_slide, is_live, is_blank)
